using System;using System.IO;using System.Linq;using Mirror;using UnityEngine;using ROM.Horde;using ROM.UI.Sprint01;using MultiFPS;
namespace ROM.Progression {
[Serializable]public sealed class RiftVendorSession {public string Token,Npc,Notice;public int Sequence=1;}
public static class RiftVendorClient {public static RiftVendorSession Current;public static void Receive(string json){Current=string.IsNullOrEmpty(json)?null:JsonUtility.FromJson<RiftVendorSession>(json);}}
public sealed partial class RiftJournalPlayer {
 string vendorToken,vendorNpc;int vendorSequence=1;double vendorCommandAt;
 public bool Trading=>exchange!=null;
 bool VendorAllowed(string npc,out RiftVillageNpc found){found=null;return isServer&&connectionToClient==NetworkServer.localConnection&&Player&&!Player.BOT&&Player.PlayerInfo.CharacterId==RiftCharacterWallet.Id&&Ensure()&&State.CharacterId==Player.PlayerInfo.CharacterId&&!Trading&&Near(npc,out found)&&found.Trades&&found.Goods&&GameManager.Gamemode.IsProtectedPosition(Player.MyCharacter.transform.position);}
 [Command]public void CmdOpenVendor(string npc){ServerOpenVendor(npc);}
 [Server]public bool ServerOpenVendor(string npc){if(!VendorAllowed(npc,out _)){Report("Comercio disponible cerca del vendedor en Host local. Clientes remotos aún no tienen cartera segura.");return false;}vendorToken=Guid.NewGuid().ToString("N");vendorNpc=npc;vendorSequence=1;VendorReply("");return true;}
 [Command]public void CmdCloseVendor(string token){if(token==vendorToken){vendorToken=vendorNpc=null;TargetVendor(connectionToClient,"");}}
 [Command]public void CmdVendorAction(string token,int sequence,string item,bool sell){bool success=ServerVendorAction(token,sequence,item,sell,out var message);VendorReply(message);if(!success)Report(message);}
 [Server]public bool ServerVendorAction(string token,int sequence,string id,bool sell,out string message){message="La oferta cambió o ya fue procesada.";if(string.IsNullOrEmpty(token)||token!=vendorToken||sequence!=vendorSequence||NetworkTime.time<vendorCommandAt)return false;message="Acercate al vendedor, salí del intercambio y revisá la cartera local.";if(!VendorAllowed(vendorNpc,out var npc))return false;var catalog=npc.Goods;int gold=RiftExplorationProgress.Gold,p0=RiftVillageSupplies.Count(0),p1=RiftVillageSupplies.Count(1);var next=JsonUtility.FromJson<JournalState>(JsonUtility.ToJson(State));if(next.LootAxes==null)next.LootAxes=new System.Collections.Generic.List<RiftLootAxe>();int price;string label;
 if(sell){if(id=="potion:0"||id=="potion:1"){int potion=id=="potion:0"?0:1;var entry=catalog.Entries?.FirstOrDefault(x=>x!=null&&x.Valid&&x.Kind!=(RiftVendorKind.Axe)&&x.Potion==potion);if(entry==null||(potion==0?p0:p1)<=0){message="No tenés esa poción para vender.";return false;}price=Mathf.FloorToInt(entry.Price*catalog.PotionResale);if(potion==0)p0--;else p1--;label=entry.Name;}else{var axe=next.LootAxes.FirstOrDefault(x=>x.Id==id);if(axe==null||next.LootAxes.Count(x=>x.Id==id)!=1||id==next.EquippedLootAxe||TradeReserved(id)){message="Solo podés vender hachas propias sin equipar ni reservar.";return false;}price=catalog.SalePrice(axe);label="Hacha de Nertör";next.LootAxes.Remove(axe);}if(price<=0||gold>1000000000-price){message="No se puede acreditar esa venta.";return false;}gold+=price;
 }else{var entry=catalog.Entries?.FirstOrDefault(x=>x!=null&&x.Valid&&x.Id==id);if(entry==null){message="Objeto no disponible.";return false;}price=entry.Price;if(gold<price){message="Oro común insuficiente.";return false;}label=entry.Name;if(entry.Kind==RiftVendorKind.Axe){if(next.LootAxes.Count>=MaximumLootAxes){message="Bolsa llena.";return false;}if(!RiftLootTuning.Load.Item(entry.Item.Id)){message="Objeto no registrado en el inventario.";return false;}int level=Mathf.Clamp(entry.Level,1,MultiFPS.Gameplay.RiftCombat.RiftProgressionCaps.Load.WorldCap);float power=RiftLootTuning.Load.Multiplier(level);next.LootAxes.Add(new RiftLootAxe{Id=Guid.NewGuid().ToString("N"),DefinitionId=entry.Item.Id,Level=level,Multiplier=power,LevelMultiplier=power,RarityMultiplier=1,RarityName="Común",RarityColor=new Color(.82f,.84f,.88f)});}else{int stock=entry.Potion==0?p0:p1;if(stock>=RiftVillageSupplies.MaxStack){message="No podés llevar más pociones.";return false;}if(entry.Potion==0)p0++;else p1++;next.Record(Catalog,MultiFPS.Gameplay.RiftProgressEvent.PotionBought,entry.Potion.ToString());}gold-=price;}
 next.EnsureDurability();try{RiftVendorPersistence.Commit(path,JsonUtility.ToJson(next),State.CharacterId,gold,p0,p1);}catch(Exception e){Debug.LogWarning("Vendor not committed: "+e.Message);message="No se pudo guardar la operación. No se confirmó la compra/venta.";return false;}State=next;vendorSequence++;vendorCommandAt=NetworkTime.time+.15;message=(sell?"Vendiste ":"Compraste ")+label+" · "+price+" oro";Push(message);return true;}
 void VendorReply(string message){if(connectionToClient!=null&&!string.IsNullOrEmpty(vendorToken))TargetVendor(connectionToClient,JsonUtility.ToJson(new RiftVendorSession{Token=vendorToken,Npc=vendorNpc,Sequence=vendorSequence,Notice=message}));}
 [TargetRpc]void TargetVendor(NetworkConnectionToClient connection,string json){RiftVendorClient.Receive(json);}
}
public static class RiftVendorPersistence {
 [Serializable]sealed class Record {public string Path,Json,Character;public int Gold,P0,P1;}
 static void Write(string path,string value){string tmp=path+".vendor-tmp";File.WriteAllText(tmp,value);if(File.Exists(path)){
  try{File.Replace(tmp,path,null);}catch(IOException){
   // A durable .pending operation remains until journal AND wallet are flushed.
   // Some Windows file systems reject Replace metadata/deletion; replay can safely redo this overwrite.
   if(!File.Exists(tmp))throw;File.Copy(tmp,path,true);File.Delete(tmp);
  }
 }else File.Move(tmp,path);}
 public static void Recover(string root){if(!Directory.Exists(root))return;foreach(var file in Directory.GetFiles(root,"vendor-*.pending")){var v=JsonUtility.FromJson<Record>(File.ReadAllText(file));if(v==null||Path.GetDirectoryName(v.Path)!=root||string.IsNullOrEmpty(v.Character))throw new IOException("Invalid vendor recovery record");Write(v.Path,v.Json);string key="ROM.CharacterWallet.v1."+v.Character;PlayerPrefs.SetInt(key+".Gold",v.Gold);PlayerPrefs.SetInt(key+".Potion.0",v.P0);PlayerPrefs.SetInt(key+".Potion.1",v.P1);PlayerPrefs.Save();File.Delete(file);}}
 public static void Commit(string path,string json,string character,int gold,int p0,int p1){string root=Path.GetDirectoryName(path);RiftTradePersistence.Recover(root);Recover(root);string file=Path.Combine(root,"vendor-"+Guid.NewGuid().ToString("N")+".pending");Write(file,JsonUtility.ToJson(new Record{Path=path,Json=json,Character=character,Gold=gold,P0=p0,P1=p1}));try{Recover(root);}catch(Exception e){Debug.LogWarning("Committed vendor recovery pending: "+e.Message);}}
}
}
